css:
[data-bz-node="loc-panels-band"]{padding-top:90px;padding-bottom:90px;}
[data-bz-node="loc-panels-band"] .bz-block{padding-block:0;}
[data-bz-node="loc-panels-row"]{gap:28px;}
[data-bz-node="loc-panels-row"] > .bz-col{display:flex;flex-direction:column;border:1px solid var(--line);padding:36px 32px;}
[data-bz-node="loc-panels-row"] .bz-text,[data-bz-node="loc-panels-row"] .bz-headingblock{max-width:none;}
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(1) p{font:700 10px/1 var(--font-body);letter-spacing:.14em;color:var(--accent);margin:0 0 12px;}
[data-bz-node="loc-panels-row"] h2{font:800 24px/1.7 var(--font-heading);letter-spacing:normal;margin:0 0 18px;}
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(3),
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(4){margin-bottom:18px;}
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(3) p,
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(4) p{font-size:15px;line-height:1.7;color:#3f3f3f;margin:0;}
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(4) a{color:var(--accent);text-decoration:none;}
[data-bz-node="loc-panels-row"] > .bz-col > .bz-block:nth-child(4) a:hover{text-decoration:underline;}
[data-bz-node="loc-panels-row"] .bz-btns{gap:26px;}
[data-bz-node="loc-panels-row"] .bz-btn{padding:0;font:700 15px/1.7 var(--font-body);text-decoration:none;}
@media (max-width:640px){[data-bz-node="loc-panels-band"]{padding-top:56px;padding-bottom:56px;}}
